"""Small persistence helpers; read only artifacts generated by this project."""

from __future__ import annotations
import hashlib
import json
from pathlib import Path
from typing import Any

import joblib


def write_json_report(payload: dict[str, Any], path: str | Path) -> None:
    """Atomic replacement prevents readers seeing half-written JSON."""
    output = Path(path)
    output.parent.mkdir(parents=True, exist_ok=True)
    temporary = output.with_suffix(output.suffix + ".tmp")
    temporary.write_text(
        json.dumps(payload, indent=2, allow_nan=False) + "\n", encoding="utf-8"
    )
    temporary.replace(output)


def save_model(model: Any, path: str | Path) -> None:
    output = Path(path)
    output.parent.mkdir(parents=True, exist_ok=True)
    temporary = output.with_suffix(".tmp")
    joblib.dump(model, temporary, compress=3)
    temporary.replace(output)


def load_model(path: str | Path) -> Any:
    """Joblib uses pickle: never load untrusted downloaded model artifacts."""
    return joblib.load(path)


def content_id(payload: dict) -> str:
    """Stable content identity excludes wall-clock training timestamps."""
    return hashlib.sha256(json.dumps(payload, sort_keys=True).encode()).hexdigest()[:16]
